import roman,re
t=roman.to_roman
assert [t(x) for x in (1,3,4,9,14,40,90,400,1994,2026,3999)]==['I','III','IV','IX','XIV','XL','XC','CD','MCMXCIV','MMXXVI','MMMCMXCIX']
D={'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
def dec(s):
    tot=0
    for i,c in enumerate(s):
        v=D[c]
        tot += -v if i+1<len(s) and D[s[i+1]]>v else v
    return tot
pat=re.compile(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})\$')
for n in range(1,4000):
    s=t(n); assert dec(s)==n and pat.match(s), (n,s)
for bad,exc in ((0,ValueError),(-1,ValueError),(4000,ValueError),('5',TypeError),(5.0,TypeError),(True,TypeError)):
    try: t(bad); raise AssertionError(bad)
    except exc: pass
print('OK', [n for n in dir(roman) if not n.startswith('_')])
"
